<?php
declare(strict_types=1);
if (file_exists(__DIR__ . '/config.php')) { header('Location: index.php'); exit; }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $name = trim($_POST['name'] ?? 'مدیر سیستم'); $email = trim($_POST['email'] ?? ''); $password = $_POST['password'] ?? '';
    if (!filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($password) < 6) $error = 'لطفاً ایمیل معتبر و گذرواژه حداقل ۶ کاراکتری وارد کنید.';
    else { if (!is_dir(__DIR__.'/storage')) mkdir(__DIR__.'/storage', 0775, true); $path=__DIR__.'/storage/ads.sqlite'; $db=new PDO('sqlite:'.$path); $sql=file_get_contents(__DIR__.'/database/schema.sql'); $db->exec($sql); $db->prepare('INSERT INTO users (name,email,password) VALUES (?,?,?)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]); file_put_contents(__DIR__.'/config.php', "<?php\nreturn " . var_export(['database'=>$path,'app_name'=>'نِگارسامانه'],true) . ";\n"); header('Location: index.php'); exit; }
}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>نصب نِگارسامانه</title><link rel="stylesheet" href="assets/style.css"></head><body class="install"><div class="install-wrap"><div class="install-brand"><span class="brand-mark">ن</span><b>نِگارسامانه</b><p>راهکار فارسی مدیریت هوشمند تبلیغات</p></div><div class="install-card"><div class="steps"><span class="done">۱</span><i></i><span class="current">۲</span><i></i><span>۳</span></div><h1>راه‌اندازی سامانه</h1><p>اطلاعات مدیر اصلی را وارد کنید تا سامانه آماده استفاده شود.</p><?php if($error): ?><div class="alert"><?= htmlspecialchars($error) ?></div><?php endif ?><form method="post"><label>نام و نام خانوادگی<input name="name" value="مدیر سیستم" required></label><label>ایمیل مدیر<input name="email" type="email" placeholder="admin@example.com" required></label><label>گذرواژه<input name="password" type="password" placeholder="حداقل ۶ کاراکتر" minlength="6" required></label><button class="primary full">نصب و ورود به سامانه ←</button></form><small class="install-note">با نصب، جداول نمونه و داده‌های آزمایشی ایجاد می‌شوند.</small></div></div></body></html>
